import fs from 'node:fs';

const html = fs.readFileSync(new URL('./index.html', import.meta.url), 'utf8');
const script = html.match(/<script type="module">([\s\S]*)<\/script>/)?.[1] ?? '';

const checks = [];

function check(name, condition) {
  checks.push({ name, ok: Boolean(condition) });
}

function has(pattern) {
  return pattern.test(html) || pattern.test(script);
}

function functionBody(name) {
  const match = script.match(new RegExp(`function ${name}\\([^)]*\\) \\{([\\s\\S]*?)\\n    \\}`));
  return match?.[1] ?? '';
}

function arrayBlock(name) {
  const start = script.indexOf(`const ${name} = [`);
  if (start === -1) return '';
  const open = script.indexOf('[', start);
  let depth = 0;
  let quote = null;
  for (let i = open; i < script.length; i += 1) {
    const char = script[i];
    const prev = script[i - 1];
    if (quote) {
      if (char === quote && prev !== '\\') quote = null;
      continue;
    }
    if (char === '\'' || char === '"' || char === '`') {
      quote = char;
      continue;
    }
    if (char === '[') depth += 1;
    if (char === ']') {
      depth -= 1;
      if (depth === 0) return script.slice(open, i + 1);
    }
  }
  return '';
}

function collectValues(block, key) {
  return [...block.matchAll(new RegExp(`${key}:\\s*'([^']+)'`, 'g'))].map((match) => match[1]);
}

function collectSourceIds(block) {
  return [...block.matchAll(/sourceIds:\s*\[([^\]]*)\]/g)]
    .flatMap((match) => [...match[1].matchAll(/'([^']+)'/g)].map((id) => id[1]));
}

function collectRelatedPersonIds(block) {
  return [...block.matchAll(/relatedPersonIds:\s*\[([^\]]*)\]/g)]
    .flatMap((match) => [...match[1].matchAll(/'([^']+)'/g)].map((id) => id[1]));
}

const sourceIds = new Set(collectValues(arrayBlock('sources'), 'id'));
const sourceBlock = arrayBlock('sources');
const segmentIds = new Set(collectValues(arrayBlock('tombSegments'), 'segmentId'));
const artifactIds = new Set(collectValues(arrayBlock('artifacts'), 'artifactId'));
const focusBlock = arrayBlock('focusItems');
const focusArtifactIds = new Set(collectValues(focusBlock, 'artifactId'));
const focusSegmentIds = collectValues(focusBlock, 'segmentId');
const peopleIds = new Set(collectValues(arrayBlock('people'), 'id'));
const relatedPersonIds = new Set(collectRelatedPersonIds(focusBlock));
const inspectActionBody = `${functionBody('inspectCurrentFocus')}\n${functionBody('inspectFocusItem')}`;

